def object_mask(grid, color):
 coords=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
 r0=min(r for r,c in coords);r1=max(r for r,c in coords);c0=min(c for r,c in coords);c1=max(c for r,c in coords)
 return np.array([[int(grid[r][c]==color) for c in range(c0,c1+1)] for r in range(r0,r1+1)])
def orient_hits(grid, outgrid, marker, bg):
 m=object_mask(grid,marker); p,h=hits_for({tuple(map(tuple,m))},grid)
 actual={(r,c) for r in range(len(grid)) for c in range(len(grid[0])) if outgrid[r][c]==marker and grid[r][c]==bg}
 return m,len(h),len(p),len(actual),len(actual-p),len(p-actual),sorted(actual-p)[:20], sorted(p-actual)[:20]
